-- Client onboarding form → Enquire (20 Sep 2026, the owner). The 38 questions
-- Daniel transcribed from Jotform now live as the Enquire form
-- "client-onboarding" (Form Builder), with his 18 Sep changes applied:
--   new Q20 "bread and butter" roles (before "who makes hiring decisions"),
--   new Q26 "who you are" statement, old Q26 → credibility statement,
--   Q32 → rebate/replacement terms, Q33 → cultural-fit case study.
-- The deck card (step onboarding_form) renders the LIVE Enquire questions in
-- its own section-at-a-time look; the journey snapshot below keeps the
-- Documents tab, the CSM sheet and validation in step.
INSERT INTO public.forms (slug, name, kind, status, schema, published_schema, sink, notify_role, theme, published_at)
VALUES ('client-onboarding', 'Client onboarding', 'general', 'live',
  '{"welcome":null,"questions":[{"id":"company_name","ref":"company_name","type":"short_text","title":"Your Company Name","required":true,"section":"Business Details"},{"id":"company_website","ref":"company_website","type":"short_text","title":"Company Website","required":true,"section":"Business Details"},{"id":"your_name","ref":"your_name","type":"full_name","title":"Your Name","required":true,"section":"Business Details"},{"id":"email","ref":"email","type":"email","title":"Your email address","required":true,"section":"Business Details"},{"id":"mobile","ref":"mobile","type":"phone","title":"What is the best mobile number to reach you?","required":true,"section":"Business Details"},{"id":"other_contacts","ref":"other_contacts","type":"long_text","title":"Please provide details of anybody else from your company that you would like to be involved in communications/ points of contact for this campaign.","required":true,"section":"Business Details","help":"If this doesn''t apply then please type ''Not Applicable''"},{"id":"billing_email","ref":"billing_email","type":"short_text","title":"Please provide the email address for your accounts/ billing department","required":false,"section":"Business Details","help":"We''ll cc this address on invoices alongside your main contact, if this doesn''t apply then please type ''Not Applicable''"},{"id":"office_address","ref":"office_address","type":"address","title":"What is the full address of your business office?","required":true,"section":"Business Details"},{"id":"timezone","ref":"timezone","type":"short_text","title":"Which time zone are you in?","required":true,"section":"Business Details"},{"id":"years_running","ref":"years_running","type":"short_text","title":"How many years has your business been running?","required":true,"section":"Business Details"},{"id":"service_types","ref":"service_types","type":"multi_choice","title":"Which recruitment services do you provide?","required":true,"section":"Business Details","help":"Select all that apply","choices":[{"id":"service_types_0","label":"Executive Search","points":0},{"id":"service_types_1","label":"Permanent","points":0},{"id":"service_types_2","label":"Temporary","points":0},{"id":"service_types_3","label":"Contract","points":0},{"id":"service_types_4","label":"Embedded","points":0}]},{"id":"countries","ref":"countries","type":"multi_choice","title":"Which country/countries does your business operate in?","required":true,"section":"Ideal Customer Profile (ICP)","help":"Please select all that apply for this campaign","choices":[{"id":"countries_0","label":"United Kingdom","points":0},{"id":"countries_1","label":"Europe","points":0},{"id":"countries_2","label":"United States","points":0},{"id":"countries_3","label":"Middle East","points":0}]},{"id":"us_states","ref":"us_states","type":"long_text","title":"If you selected the United States, which States are relevant to this campaign?","required":true,"section":"Ideal Customer Profile (ICP)","help":"List specific States or write “Nationwide” if there’s no restriction. If you didn''t select the US please write ''Not Applicable''."},{"id":"industry_or_talent_led","ref":"industry_or_talent_led","type":"multi_choice","title":"Would you say you''re more industry led or talent led?","required":true,"section":"Ideal Customer Profile (ICP)","choices":[{"id":"industry_or_talent_led_0","label":"Industry led (you place most/all types of candidates within specific industries/sectors that you specialise in)","points":0},{"id":"industry_or_talent_led_1","label":"Talent led (you place specific types/ levels of candidates across any/ multiple sectors)","points":0}]},{"id":"talent_led_indicators","ref":"talent_led_indicators","type":"long_text","title":"If you said more candidate focused then what are some key indicators/ attributes of companies that have a need for the types of candidates that you place?","required":true,"section":"Ideal Customer Profile (ICP)","help":"For example if you only place finance professionals then a key indicator of companies that hire finance professionals are one’s that have a CFO because that means they have a finance department"},{"id":"target_industries","ref":"target_industries","type":"long_text","title":"Please provide all relevant industries that you would like us to target for this campaign","required":true,"section":"Ideal Customer Profile (ICP)","help":"Example: “Renewable energy ”, “FMCG”, “Construction\", \"SAAS\""},{"id":"industry_keywords","ref":"industry_keywords","type":"long_text","title":"Please let us know the relevant industry keywords we should use in targeting?","required":true,"section":"Ideal Customer Profile (ICP)","help":"Which words appear in your ideal client''s LinkedIn company description? For example: \"software development\", \"manufacturing\", \"supply chain\", \"B2B sales\""},{"id":"icp_criteria","ref":"icp_criteria","type":"long_text","title":"What type of companies are a good fit? In other words, what is your ICP? Include any/all criteria that matters to you.","required":true,"section":"Ideal Customer Profile (ICP)","help":"For example e.g. Revenue, Number of employees, Funding Stage, Locations etc). These answers will help guide the lead list building process."},{"id":"candidate_types","ref":"candidate_types","type":"long_text","title":"We want to know about the types of candidates you specialise in placing. Please tell us firstly what are the job titles that you specialise in placing? Secondly what level of role''s do you place? Thirdly what is the collective term for these candidates?","required":true,"section":"Ideal Customer Profile (ICP)","help":"Please provide roles/ job titles for each industry named along with level (for example, entry level, c suite etc). For collective term we mean if you place accountants, auditors and financial directors then the collective term is ''finance professionals''"},{"id":"bread_and_butter_roles","ref":"bread_and_butter_roles","type":"long_text","required":true,"section":"Ideal Customer Profile (ICP)","title":"What types of candidates are your “bread and butter” — the roles where you are most confident you can source and place high-quality candidates quickly?","help":"Think about roles where, if a client gave you a vacancy today, you would be confident in presenting suitable candidates within approximately 48 hours."},{"id":"decision_makers","ref":"decision_makers","type":"long_text","title":"Who is primarily responsible for making/influencing hiring decisions for each of the roles you mentioned in the previous question?","required":true,"section":"Ideal Customer Profile (ICP)","help":"Please include primary (e.g. CEO, Founder, MD etc) and secondary decision makers (e.g. Chief of People, HR Director, CTO, COO)"},{"id":"example_companies","ref":"example_companies","type":"long_text","title":"Please list 5-10 examples of companies in each market that you target that you would like to work with.","required":true,"section":"Ideal Customer Profile (ICP)","help":"Please include each company''s website URL"},{"id":"elevator_pitch","ref":"elevator_pitch","type":"long_text","title":"What''s your ''Elevator Pitch''?","required":true,"section":"Business Development","help":"If you had 30 seconds to explain what you do to a potential client, what would you say? Focus on who you help, the problem you solve, and the outcome you deliver. Include any awards or widely known companies that you''ve helped or a noteworthy statistic regarding your services. Importantly make sure to keep it short and sweet."},{"id":"who_you_are","ref":"who_you_are","type":"long_text","required":true,"section":"Business Development","title":"Please provide a clear, concise statement explaining who you are, what your business does, and who you specialise in supporting."},{"id":"credibility_statement","ref":"credibility_statement","type":"long_text","title":"Please provide a short credibility statement explaining why a prospective client should trust you and choose to work with you.","required":true,"section":"Business Development"},{"id":"client_problems","ref":"client_problems","type":"long_text","title":"What are the 2-3 main problems that your clients face with hiring internally? Separately, what are the 2-3 main problems that your clients face when working with recruitment agencies?","required":true,"section":"Business Development","help":"List the top hiring problems your ideal clients are actively dealing with. These should be specific hiring challenges that are on their mind frequently, not general business issues. e.g. Can’t find qualified candidates, Low response rates from good candidates, Low quality candidates from etc"},{"id":"problem_impact","ref":"problem_impact","type":"long_text","title":"How do these problems impact them in their world?","required":true,"section":"Business Development","help":"Describe how these problems affect your clients day-to-day. Focus on the knock-on effects to time, revenue, delivery, or workload. e.g. Projects are delayed, Senior staff are stretched thin, Revenue targets are being missed"},{"id":"problem_consequences","ref":"problem_consequences","type":"long_text","title":"What happens if these problems continue without being solved?","required":true,"section":"Business Development","help":"Explain the longer-term consequences if the hiring issues continue. Think about risk, growth, and opportunity cost. e.g. Investor''s get frustrated, Good candidates go to competitors, Growth plans stall or fail, Key team members begin to leave due to mounting pressure as a result of being under resourced"},{"id":"fees","ref":"fees","type":"long_text","title":"What are your fee''s?","required":true,"section":"Business Development","help":"Please let us know in as much detail as possible your pricing structure based on the recruitment service you provide. On perm we want to know contingent fee''s and retainer fee''s as a percentage. On temp we want to know hourly rates"},{"id":"rebate_terms","ref":"rebate_terms","type":"long_text","title":"What are your rebate/replacement terms?","required":true,"section":"Business Development","help":"If yes, please explain in detail"},{"id":"cultural_fit_case_study","ref":"cultural_fit_case_study","type":"long_text","title":"Please provide a case study that demonstrates a strong cultural fit with the types of companies you want us to target. Where possible, explain the client''s situation, the type of role(s) you worked on, your recruitment process, and the outcome.","required":true,"section":"Business Development"},{"id":"always_look_candidates","ref":"always_look_candidates","type":"long_text","title":"Which type of candidate are your clients ALWAYS willing to take a look at (even when not hiring immediately)?","required":true,"section":"Business Development","help":"These should be candidates you can place."},{"id":"pr_events","ref":"pr_events","type":"long_text","title":"Has your company recently had any good PR or noteworthy presence at industry relevant events?","required":true,"section":"Business Development","help":"If yes, please explain as much as possible"},{"id":"notable_clients","ref":"notable_clients","type":"long_text","title":"Who are some clients that you''ve worked with that are well known in the industry?","required":true,"section":"Business Development","help":"These should be notable companies that your prospects will recognise from their sector and understand your calibre of clients, this will give a higher level of perceived credibility. Please don''t list any companies that you have NDA''s in place with."},{"id":"misunderstood_roles","ref":"misunderstood_roles","type":"long_text","title":"List some roles that you''d recruit for which are commonly misunderstood by generalist recruiters, and what types of candidates do they typically submit as a result?","required":true,"section":"Business Development","help":"e.g. For a recruiter specialising in town planning, the role ''Transport Planner with development planning experience'' is commonly misunderstood. Generalist recruiters often submit Town Planners, Transport Modellers or Highways Engineers because the job titles sound related - but they''re actually distinct specialisms with different skill sets and career paths."},{"id":"meetings_per_consultant","ref":"meetings_per_consultant","type":"long_text","title":"On average, how many new client sales meetings are each of your consultants sitting per month?","required":true,"section":"Goals","help":"If you don''t have 180/360 consultants underneath you yet then please let us know how many new sales meetings you are sitting per month on average"},{"id":"consultant_first_year_revenue","ref":"consultant_first_year_revenue","type":"long_text","title":"When bringing on a new consultant, how much revenue do you expect them to generate in their first year?","required":true,"section":"Goals","help":"We want to know the minimum standard, typically this figure is between 50k-80k. We ask for this to understand your in-house standards so that we can ensure the value we bring exceeds expectations"},{"id":"client_12m_value","ref":"client_12m_value","type":"short_text","title":"On average, what is a new client worth to you over a 12 month period?","required":false,"section":"Goals"},{"id":"first_30_day_wins","ref":"first_30_day_wins","type":"long_text","title":"What win/ wins would you like to see in the first 30 days of the campaign?","required":true,"section":"Goals","help":"Even though the initial campaign is 90 days we know you''re judging us based off of the first 30 days."},{"id":"success_definition","ref":"success_definition","type":"long_text","title":"What does success look like to you? In other words - what result would you like us to achieve in order for you to renew with us at the end of your trial campaign?","required":true,"section":"Goals","help":"We would love this to be a long term relationship, so how can we ensure this from our end?"}],"logic":[],"endings":[{"id":"end_done","kind":"message","title":"Thank you — that''s everything we need about your business.","body":"Your CSM will read this before your onboarding call.","outcome":"submitted"}],"default_ending":"end_done","hidden":["client_profile_id","company"],"scoring":{"enabled":false,"threshold_pct":70,"below_threshold_ending":null}}'::jsonb,
