   SET config = config || jsonb_build_object('enquire_slug', 'client-onboarding', 'questions', '[{"key":"company_name","label":"Your Company Name","type":"text","required":true,"section":"Business Details","prefill":"company_name"},{"key":"company_website","label":"Company Website","type":"text","required":true,"section":"Business Details"},{"key":"your_name","label":"Your Name","type":"fullname","required":true,"section":"Business Details","prefill":"contact_name"},{"key":"email","label":"Your email address","type":"email","required":true,"section":"Business Details","prefill":"email"},{"key":"mobile","label":"What is the best mobile number to reach you?","type":"phone","required":true,"section":"Business Details"},{"key":"other_contacts","label":"Please provide details of anybody else from your company that you would like to be involved in communications/ points of contact for this campaign.","type":"textarea","required":true,"help":"If this doesn''t apply then please type ''Not Applicable''","section":"Business Details"},{"key":"billing_email","label":"Please provide the email address for your accounts/ billing department","type":"text","required":false,"help":"We''ll cc this address on invoices alongside your main contact, if this doesn''t apply then please type ''Not Applicable''","section":"Business Details"},{"key":"office_address","label":"What is the full address of your business office?","type":"address","required":true,"section":"Business Details"},{"key":"timezone","label":"Which time zone are you in?","type":"text","required":true,"section":"Business Details"},{"key":"years_running","label":"How many years has your business been running?","type":"text","required":true,"section":"Business Details"},{"key":"service_types","label":"Which recruitment services do you provide?","type":"checkbox","required":true,"help":"Select all that apply","section":"Business Details","options":["Executive Search","Permanent","Temporary","Contract","Embedded"]},{"key":"countries","label":"Which country/countries does your business operate in?","type":"checkbox","required":true,"help":"Please select all that apply for this campaign","section":"Ideal Customer Profile (ICP)","options":["United Kingdom","Europe","United States","Middle East"]},{"key":"us_states","label":"If you selected the United States, which States are relevant to this campaign?","type":"textarea","required":true,"help":"List specific States or write “Nationwide” if there’s no restriction. If you didn''t select the US please write ''Not Applicable''.","section":"Ideal Customer Profile (ICP)"},{"key":"industry_or_talent_led","label":"Would you say you''re more industry led or talent led?","type":"checkbox","required":true,"section":"Ideal Customer Profile (ICP)","options":["Industry led (you place most/all types of candidates within specific industries/sectors that you specialise in)","Talent led (you place specific types/ levels of candidates across any/ multiple sectors)"]},{"key":"talent_led_indicators","label":"If you said more candidate focused then what are some key indicators/ attributes of companies that have a need for the types of candidates that you place?","type":"textarea","required":true,"help":"For example if you only place finance professionals then a key indicator of companies that hire finance professionals are one’s that have a CFO because that means they have a finance department","section":"Ideal Customer Profile (ICP)"},{"key":"target_industries","label":"Please provide all relevant industries that you would like us to target for this campaign","type":"textarea","required":true,"help":"Example: “Renewable energy ”, “FMCG”, “Construction\", \"SAAS\"","section":"Ideal Customer Profile (ICP)"},{"key":"industry_keywords","label":"Please let us know the relevant industry keywords we should use in targeting?","type":"textarea","required":true,"help":"Which words appear in your ideal client''s LinkedIn company description? For example: \"software development\", \"manufacturing\", \"supply chain\", \"B2B sales\"","section":"Ideal Customer Profile (ICP)"},{"key":"icp_criteria","label":"What type of companies are a good fit? In other words, what is your ICP? Include any/all criteria that matters to you.","type":"textarea","required":true,"help":"For example e.g. Revenue, Number of employees, Funding Stage, Locations etc). These answers will help guide the lead list building process.","section":"Ideal Customer Profile (ICP)"},{"key":"candidate_types","label":"We want to know about the types of candidates you specialise in placing. Please tell us firstly what are the job titles that you specialise in placing? Secondly what level of role''s do you place? Thirdly what is the collective term for these candidates?","type":"textarea","required":true,"help":"Please provide roles/ job titles for each industry named along with level (for example, entry level, c suite etc). For collective term we mean if you place accountants, auditors and financial directors then the collective term is ''finance professionals''","section":"Ideal Customer Profile (ICP)"},{"key":"bread_and_butter_roles","label":"What types of candidates are your “bread and butter” — the roles where you are most confident you can source and place high-quality candidates quickly?","type":"textarea","required":true,"help":"Think about roles where, if a client gave you a vacancy today, you would be confident in presenting suitable candidates within approximately 48 hours.","section":"Ideal Customer Profile (ICP)"},{"key":"decision_makers","label":"Who is primarily responsible for making/influencing hiring decisions for each of the roles you mentioned in the previous question?","type":"textarea","required":true,"help":"Please include primary (e.g. CEO, Founder, MD etc) and secondary decision makers (e.g. Chief of People, HR Director, CTO, COO)","section":"Ideal Customer Profile (ICP)"},{"key":"example_companies","label":"Please list 5-10 examples of companies in each market that you target that you would like to work with.","type":"textarea","required":true,"help":"Please include each company''s website URL","section":"Ideal Customer Profile (ICP)"},{"key":"elevator_pitch","label":"What''s your ''Elevator Pitch''?","type":"textarea","required":true,"help":"If you had 30 seconds to explain what you do to a potential client, what would you say? Focus on who you help, the problem you solve, and the outcome you deliver. Include any awards or widely known companies that you''ve helped or a noteworthy statistic regarding your services. Importantly make sure to keep it short and sweet.","section":"Business Development"},{"key":"who_you_are","label":"Please provide a clear, concise statement explaining who you are, what your business does, and who you specialise in supporting.","type":"textarea","required":true,"section":"Business Development"},{"key":"credibility_statement","label":"Please provide a short credibility statement explaining why a prospective client should trust you and choose to work with you.","type":"textarea","required":true,"section":"Business Development"},{"key":"client_problems","label":"What are the 2-3 main problems that your clients face with hiring internally? Separately, what are the 2-3 main problems that your clients face when working with recruitment agencies?","type":"textarea","required":true,"help":"List the top hiring problems your ideal clients are actively dealing with. These should be specific hiring challenges that are on their mind frequently, not general business issues. e.g. Can’t find qualified candidates, Low response rates from good candidates, Low quality candidates from etc","section":"Business Development"},{"key":"problem_impact","label":"How do these problems impact them in their world?","type":"textarea","required":true,"help":"Describe how these problems affect your clients day-to-day. Focus on the knock-on effects to time, revenue, delivery, or workload. e.g. Projects are delayed, Senior staff are stretched thin, Revenue targets are being missed","section":"Business Development"},{"key":"problem_consequences","label":"What happens if these problems continue without being solved?","type":"textarea","required":true,"help":"Explain the longer-term consequences if the hiring issues continue. Think about risk, growth, and opportunity cost. e.g. Investor''s get frustrated, Good candidates go to competitors, Growth plans stall or fail, Key team members begin to leave due to mounting pressure as a result of being under resourced","section":"Business Development"},{"key":"fees","label":"What are your fee''s?","type":"textarea","required":true,"help":"Please let us know in as much detail as possible your pricing structure based on the recruitment service you provide. On perm we want to know contingent fee''s and retainer fee''s as a percentage. On temp we want to know hourly rates","section":"Business Development"},{"key":"rebate_terms","label":"What are your rebate/replacement terms?","type":"textarea","required":true,"help":"If yes, please explain in detail","section":"Business Development"},{"key":"cultural_fit_case_study","label":"Please provide a case study that demonstrates a strong cultural fit with the types of companies you want us to target. Where possible, explain the client''s situation, the type of role(s) you worked on, your recruitment process, and the outcome.","type":"textarea","required":true,"section":"Business Development"},{"key":"always_look_candidates","label":"Which type of candidate are your clients ALWAYS willing to take a look at (even when not hiring immediately)?","type":"textarea","required":true,"help":"These should be candidates you can place.","section":"Business Development"},{"key":"pr_events","label":"Has your company recently had any good PR or noteworthy presence at industry relevant events?","type":"textarea","required":true,"help":"If yes, please explain as much as possible","section":"Business Development"},{"key":"notable_clients","label":"Who are some clients that you''ve worked with that are well known in the industry?","type":"textarea","required":true,"help":"These should be notable companies that your prospects will recognise from their sector and understand your calibre of clients, this will give a higher level of perceived credibility. Please don''t list any companies that you have NDA''s in place with.","section":"Business Development"},{"key":"misunderstood_roles","label":"List some roles that you''d recruit for which are commonly misunderstood by generalist recruiters, and what types of candidates do they typically submit as a result?","type":"textarea","required":true,"help":"e.g. For a recruiter specialising in town planning, the role ''Transport Planner with development planning experience'' is commonly misunderstood. Generalist recruiters often submit Town Planners, Transport Modellers or Highways Engineers because the job titles sound related - but they''re actually distinct specialisms with different skill sets and career paths.","section":"Business Development"},{"key":"meetings_per_consultant","label":"On average, how many new client sales meetings are each of your consultants sitting per month?","type":"textarea","required":true,"help":"If you don''t have 180/360 consultants underneath you yet then please let us know how many new sales meetings you are sitting per month on average","section":"Goals"},{"key":"consultant_first_year_revenue","label":"When bringing on a new consultant, how much revenue do you expect them to generate in their first year?","type":"textarea","required":true,"help":"We want to know the minimum standard, typically this figure is between 50k-80k. We ask for this to understand your in-house standards so that we can ensure the value we bring exceeds expectations","section":"Goals"},{"key":"client_12m_value","label":"On average, what is a new client worth to you over a 12 month period?","type":"text","required":false,"section":"Goals"},{"key":"first_30_day_wins","label":"What win/ wins would you like to see in the first 30 days of the campaign?","type":"textarea","required":true,"help":"Even though the initial campaign is 90 days we know you''re judging us based off of the first 30 days.","section":"Goals"},{"key":"success_definition","label":"What does success look like to you? In other words - what result would you like us to achieve in order for you to renew with us at the end of your trial campaign?","type":"textarea","required":true,"help":"We would love this to be a long term relationship, so how can we ensure this from our end?","section":"Goals"}]'::jsonb, 'sections', '["Business Details","Ideal Customer Profile (ICP)","Business Development","Goals"]'::jsonb)
 WHERE step_key = 'onboarding_form';

-- Proof
SELECT
  (SELECT jsonb_array_length(published_schema->'questions') FROM public.forms WHERE slug='client-onboarding') AS enquire_questions,
  (SELECT config->>'enquire_slug' FROM public.client_flow_steps WHERE step_key='onboarding_form') AS step_slug,
  (SELECT jsonb_array_length(config->'questions') FROM public.client_flow_steps WHERE step_key='onboarding_form') AS snapshot_questions;
